insert into public.exercises
  (id, owner_id, name, category, measurement, muscle_groups, equipment, instructions, video_url)
values
  ('11111111-1111-4111-8111-111111111116', null, 'Front Squat', 'strength', 'weight_reps', array['quads', 'glutes', 'core'], array['barbell', 'rack'], 'Rest the bar on the front delts with elbows high. Sit between the hips, keep the torso upright, and stand by driving the floor away.', 'https://www.youtube.com/results?search_query=Front%20Squat%20proper%20form'),
  ('11111111-1111-4111-8111-111111111117', null, 'Pause Squat', 'strength', 'weight_reps', array['quads', 'glutes', 'core'], array['barbell', 'rack'], 'Descend as in a back squat and pause for a full second at the bottom without relaxing. Drive up without bouncing.', 'https://www.youtube.com/results?search_query=Pause%20Squat%20proper%20form'),
  ('11111111-1111-4111-8111-111111111118', null, 'Box Squat', 'strength', 'weight_reps', array['quads', 'glutes', 'hamstrings'], array['barbell', 'rack', 'box'], 'Sit back to a box, pause briefly without collapsing, then explode up while keeping the shins fairly vertical.', 'https://www.youtube.com/results?search_query=Box%20Squat%20proper%20form'),
  ('11111111-1111-4111-8111-111111111119', null, 'Sumo Deadlift', 'strength', 'weight_reps', array['glutes', 'hamstrings', 'quads', 'back'], array['barbell'], 'Take a wide stance with toes out, grip the bar inside the knees. Push the floor apart and keep the chest up as the bar rises.', 'https://www.youtube.com/results?search_query=Sumo%20Deadlift%20proper%20form'),
  ('11111111-1111-4111-8111-111111111120', null, 'Trap Bar Deadlift', 'strength', 'weight_reps', array['quads', 'glutes', 'hamstrings', 'back'], array['trap bar'], 'Stand inside the trap bar, grab the handles, brace, and stand tall by pushing the floor away. Lower with a controlled hinge.', 'https://www.youtube.com/results?search_query=Trap%20Bar%20Deadlift%20proper%20form'),
  ('11111111-1111-4111-8111-111111111121', null, 'Deficit Deadlift', 'strength', 'weight_reps', array['hamstrings', 'glutes', 'back'], array['barbell', 'plates'], 'Stand on a small plate or platform. Hinge to the bar and pull with the same cues as a conventional deadlift, using the extra range.', 'https://www.youtube.com/results?search_query=Deficit%20Deadlift%20proper%20form'),
  ('11111111-1111-4111-8111-111111111122', null, 'Rack Pull', 'strength', 'weight_reps', array['back', 'glutes', 'hamstrings'], array['barbell', 'rack'], 'Set the bar just below or above the knee in a rack. Brace and lock out the hips and back without jerking.', 'https://www.youtube.com/results?search_query=Rack%20Pull%20proper%20form'),
  ('11111111-1111-4111-8111-111111111123', null, 'Good Morning', 'strength', 'weight_reps', array['hamstrings', 'glutes', 'lower back'], array['barbell'], 'Bar on the upper back, soft knees. Hinge until the torso is near parallel, then drive the hips forward to stand.', 'https://www.youtube.com/results?search_query=Good%20Morning%20proper%20form'),
  ('11111111-1111-4111-8111-111111111124', null, 'Barbell Hip Thrust', 'strength', 'weight_reps', array['glutes', 'hamstrings'], array['barbell', 'bench'], 'Upper back on a bench, bar over the hips. Drive through the heels until the hips lock out in a straight line from knees to shoulders.', 'https://www.youtube.com/results?search_query=Barbell%20Hip%20Thrust%20proper%20form'),
  ('11111111-1111-4111-8111-111111111125', null, 'Close-Grip Bench Press', 'strength', 'weight_reps', array['triceps', 'chest', 'shoulders'], array['barbell', 'bench'], 'Grip just inside shoulder width. Lower the bar to the lower chest with elbows closer to the torso, then press up.', 'https://www.youtube.com/results?search_query=Close-Grip%20Bench%20Press%20proper%20form'),
  ('11111111-1111-4111-8111-111111111126', null, 'Incline Barbell Bench Press', 'strength', 'weight_reps', array['chest', 'shoulders', 'triceps'], array['barbell', 'incline bench'], 'Set the bench to about 30 degrees. Lower the bar to the upper chest and press until the arms lock out.', 'https://www.youtube.com/results?search_query=Incline%20Barbell%20Bench%20Press%20proper%20form'),
  ('11111111-1111-4111-8111-111111111127', null, 'Decline Bench Press', 'strength', 'weight_reps', array['chest', 'triceps'], array['barbell', 'decline bench'], 'Secure the legs on a decline bench. Lower the bar to the lower chest and press up without bouncing.', 'https://www.youtube.com/results?search_query=Decline%20Bench%20Press%20proper%20form'),
  ('11111111-1111-4111-8111-111111111128', null, 'Floor Press', 'strength', 'weight_reps', array['triceps', 'chest', 'shoulders'], array['barbell'], 'Lie on the floor and lower the bar until the triceps touch the ground. Pause and press back up.', 'https://www.youtube.com/results?search_query=Floor%20Press%20proper%20form'),
  ('11111111-1111-4111-8111-111111111129', null, 'Push Press', 'strength', 'weight_reps', array['shoulders', 'triceps', 'legs'], array['barbell'], 'Dip the knees slightly and drive the bar overhead with the legs, then lock out the arms. Lower under control.', 'https://www.youtube.com/results?search_query=Push%20Press%20proper%20form'),
  ('11111111-1111-4111-8111-111111111130', null, 'Power Clean', 'strength', 'weight_reps', array['full body'], array['barbell'], 'Pull the bar from the floor, extend the hips explosively, and catch it in a quarter-squat front-rack. Stand to finish.', 'https://www.youtube.com/results?search_query=Power%20Clean%20proper%20form'),
  ('11111111-1111-4111-8111-111111111131', null, 'Hang Clean', 'strength', 'weight_reps', array['full body'], array['barbell'], 'Start with the bar at mid-thigh. Hinge slightly, extend hard, and catch in the front rack.', 'https://www.youtube.com/results?search_query=Hang%20Clean%20proper%20form'),
  ('11111111-1111-4111-8111-111111111132', null, 'Barbell Shrug', 'strength', 'weight_reps', array['traps'], array['barbell'], 'Hold the bar at the thighs and shrug the shoulders straight up. Pause at the top, then lower slowly.', 'https://www.youtube.com/results?search_query=Barbell%20Shrug%20proper%20form'),
  ('11111111-1111-4111-8111-111111111133', null, 'Pendlay Row', 'strength', 'weight_reps', array['upper back', 'lats', 'biceps'], array['barbell'], 'Hinge to parallel, let the bar rest on the floor each rep. Row explosively to the lower chest and lower with control.', 'https://www.youtube.com/results?search_query=Pendlay%20Row%20proper%20form'),
  ('11111111-1111-4111-8111-111111111134', null, 'Barbell Lunge', 'strength', 'weight_reps', array['quads', 'glutes', 'hamstrings'], array['barbell'], 'Bar on the back, step forward and drop the back knee toward the floor. Drive through the front foot to stand.', 'https://www.youtube.com/results?search_query=Barbell%20Lunge%20proper%20form'),
  ('11111111-1111-4111-8111-111111111135', null, 'Walking Lunge', 'strength', 'weight_reps', array['quads', 'glutes', 'hamstrings'], array['dumbbells'], 'Step forward into a lunge, then bring the back foot through into the next step. Keep the torso tall.', 'https://www.youtube.com/results?search_query=Walking%20Lunge%20proper%20form'),
  ('11111111-1111-4111-8111-111111111136', null, 'Bulgarian Split Squat', 'strength', 'weight_reps', array['quads', 'glutes'], array['dumbbells', 'bench'], 'Rear foot on a bench, front foot far enough forward that the knee tracks over the mid-foot. Drop straight down and stand.', 'https://www.youtube.com/results?search_query=Bulgarian%20Split%20Squat%20proper%20form'),
  ('11111111-1111-4111-8111-111111111137', null, 'Landmine Press', 'strength', 'weight_reps', array['shoulders', 'chest', 'core'], array['barbell', 'landmine'], 'Hold the bar at the shoulder, brace the core, and press it up and slightly forward until the arm locks out.', 'https://www.youtube.com/results?search_query=Landmine%20Press%20proper%20form'),
  ('11111111-1111-4111-8111-111111111138', null, 'Standing Calf Raise', 'strength', 'weight_reps', array['calves'], array['barbell', 'step'], 'Rise onto the balls of the feet through a full range, pause, then lower the heels below the step.', 'https://www.youtube.com/results?search_query=Standing%20Calf%20Raise%20proper%20form'),
  ('11111111-1111-4111-8111-111111111139', null, 'Dumbbell Bench Press', 'strength', 'weight_reps', array['chest', 'triceps', 'shoulders'], array['dumbbells', 'bench'], 'Press the dumbbells from chest height to lockout, keeping the wrists stacked over the elbows.', 'https://www.youtube.com/results?search_query=Dumbbell%20Bench%20Press%20proper%20form'),
  ('11111111-1111-4111-8111-111111111140', null, 'Incline Dumbbell Bench Press', 'strength', 'weight_reps', array['chest', 'shoulders', 'triceps'], array['dumbbells', 'incline bench'], 'On a low incline, lower the bells to the upper chest with elbows about 45 degrees, then press up.', 'https://www.youtube.com/results?search_query=Incline%20Dumbbell%20Bench%20Press%20proper%20form'),
  ('11111111-1111-4111-8111-111111111141', null, 'Dumbbell Shoulder Press', 'strength', 'weight_reps', array['shoulders', 'triceps'], array['dumbbells'], 'Press the dumbbells from ear height to lockout overhead. Do not flare the ribs.', 'https://www.youtube.com/results?search_query=Dumbbell%20Shoulder%20Press%20proper%20form'),
  ('11111111-1111-4111-8111-111111111142', null, 'Arnold Press', 'strength', 'weight_reps', array['shoulders', 'triceps'], array['dumbbells'], 'Start with palms facing you at the shoulders, rotate as you press so the palms face forward at the top.', 'https://www.youtube.com/results?search_query=Arnold%20Press%20proper%20form'),
  ('11111111-1111-4111-8111-111111111143', null, 'One-Arm Dumbbell Row', 'strength', 'weight_reps', array['lats', 'upper back', 'biceps'], array['dumbbells', 'bench'], 'Brace on a bench, pull the dumbbell to the hip, and lower until the shoulder blade reaches.', 'https://www.youtube.com/results?search_query=One-Arm%20Dumbbell%20Row%20proper%20form'),
  ('11111111-1111-4111-8111-111111111144', null, 'Dumbbell Romanian Deadlift', 'strength', 'weight_reps', array['hamstrings', 'glutes'], array['dumbbells'], 'Hinge with a soft knee bend, sliding the bells down the thighs until the hamstrings stretch, then stand.', 'https://www.youtube.com/results?search_query=Dumbbell%20Romanian%20Deadlift%20proper%20form'),
  ('11111111-1111-4111-8111-111111111145', null, 'Goblet Squat', 'strength', 'weight_reps', array['quads', 'glutes', 'core'], array['dumbbells', 'kettlebell'], 'Hold a dumbbell or kettlebell at the chest. Sit between the hips, keep the elbows inside the knees, and stand.', 'https://www.youtube.com/results?search_query=Goblet%20Squat%20proper%20form'),
  ('11111111-1111-4111-8111-111111111146', null, 'Dumbbell Fly', 'strength', 'weight_reps', array['chest'], array['dumbbells', 'bench'], 'With a slight elbow bend, open the arms in a wide arc until a chest stretch, then bring the bells back together.', 'https://www.youtube.com/results?search_query=Dumbbell%20Fly%20proper%20form'),
  ('11111111-1111-4111-8111-111111111147', null, 'Lateral Raise', 'strength', 'weight_reps', array['shoulders'], array['dumbbells'], 'Raise the dumbbells out to the sides until just below shoulder height, leading with the elbows. Lower slowly.', 'https://www.youtube.com/results?search_query=Lateral%20Raise%20proper%20form'),
  ('11111111-1111-4111-8111-111111111148', null, 'Front Raise', 'strength', 'weight_reps', array['shoulders'], array['dumbbells'], 'Raise the bells in front of you to shoulder height with a slight elbow bend. Avoid swinging.', 'https://www.youtube.com/results?search_query=Front%20Raise%20proper%20form'),
  ('11111111-1111-4111-8111-111111111149', null, 'Rear Delt Fly', 'strength', 'weight_reps', array['rear delts', 'upper back'], array['dumbbells'], 'Hinge to 45 degrees and raise the arms out to the sides, squeezing the rear delts at the top.', 'https://www.youtube.com/results?search_query=Rear%20Delt%20Fly%20proper%20form'),
  ('11111111-1111-4111-8111-111111111150', null, 'Hammer Curl', 'strength', 'weight_reps', array['biceps', 'forearms'], array['dumbbells'], 'Curl with a neutral grip (thumbs up). Keep the elbows pinned and lower under control.', 'https://www.youtube.com/results?search_query=Hammer%20Curl%20proper%20form'),
  ('11111111-1111-4111-8111-111111111151', null, 'Incline Dumbbell Curl', 'strength', 'weight_reps', array['biceps'], array['dumbbells', 'incline bench'], 'Sit on an incline bench and curl from a fully stretched position without swinging the shoulders.', 'https://www.youtube.com/results?search_query=Incline%20Dumbbell%20Curl%20proper%20form'),
  ('11111111-1111-4111-8111-111111111152', null, 'Overhead Triceps Extension', 'strength', 'weight_reps', array['triceps'], array['dumbbells'], 'Hold a dumbbell overhead, bend the elbows to lower it behind the head, then extend until the arms lock.', 'https://www.youtube.com/results?search_query=Overhead%20Triceps%20Extension%20proper%20form'),
  ('11111111-1111-4111-8111-111111111153', null, 'Dumbbell Pullover', 'strength', 'weight_reps', array['lats', 'chest'], array['dumbbells', 'bench'], 'Lower a dumbbell behind the head with soft elbows until a lat stretch, then pull it back over the chest.', 'https://www.youtube.com/results?search_query=Dumbbell%20Pullover%20proper%20form'),
  ('11111111-1111-4111-8111-111111111154', null, 'Farmer Carry', 'strength', 'duration', array['forearms', 'traps', 'core'], array['dumbbells', 'kettlebells'], 'Pick up a heavy pair of bells, brace, and walk with short even steps. Log the loaded walking time.', 'https://www.youtube.com/results?search_query=Farmer%20Carry%20proper%20form'),
  ('11111111-1111-4111-8111-111111111155', null, 'Kettlebell Swing', 'strength', 'weight_reps', array['glutes', 'hamstrings', 'core'], array['kettlebell'], 'Hinge and hike the bell back, then snap the hips to float it to chest height. Do not squat the swing.', 'https://www.youtube.com/results?search_query=Kettlebell%20Swing%20proper%20form'),
  ('11111111-1111-4111-8111-111111111156', null, 'Turkish Get-Up', 'strength', 'reps', array['full body'], array['kettlebell'], 'From lying, press the bell up and stand through a controlled sequence, eyes on the weight. Reverse to the floor.', 'https://www.youtube.com/results?search_query=Turkish%20Get-Up%20proper%20form'),
  ('11111111-1111-4111-8111-111111111157', null, 'Leg Press', 'strength', 'weight_reps', array['quads', 'glutes', 'hamstrings'], array['leg press'], 'Feet mid-platform, lower until the thighs approach the torso without the low back rounding, then press through the whole foot.', 'https://www.youtube.com/results?search_query=Leg%20Press%20proper%20form'),
  ('11111111-1111-4111-8111-111111111158', null, 'Hack Squat', 'strength', 'weight_reps', array['quads', 'glutes'], array['hack squat'], 'Back against the pad, descend until the thighs are at least parallel, then drive up without locking harshly.', 'https://www.youtube.com/results?search_query=Hack%20Squat%20proper%20form'),
  ('11111111-1111-4111-8111-111111111159', null, 'Leg Extension', 'strength', 'weight_reps', array['quads'], array['leg extension'], 'Extend the knees until the legs are straight, pause, and lower without slamming the stack.', 'https://www.youtube.com/results?search_query=Leg%20Extension%20proper%20form'),
  ('11111111-1111-4111-8111-111111111160', null, 'Lying Leg Curl', 'strength', 'weight_reps', array['hamstrings'], array['leg curl'], 'Curl the pad toward the glutes, squeeze, and lower slowly. Keep the hips down on the bench.', 'https://www.youtube.com/results?search_query=Lying%20Leg%20Curl%20proper%20form'),
  ('11111111-1111-4111-8111-111111111161', null, 'Seated Leg Curl', 'strength', 'weight_reps', array['hamstrings'], array['leg curl'], 'Secure the lap pad and curl the heels under the seat. Control the return.', 'https://www.youtube.com/results?search_query=Seated%20Leg%20Curl%20proper%20form'),
  ('11111111-1111-4111-8111-111111111162', null, 'Seated Calf Raise', 'strength', 'weight_reps', array['calves'], array['calf machine'], 'Rise onto the balls of the feet, pause, and lower the heels through a full stretch.', 'https://www.youtube.com/results?search_query=Seated%20Calf%20Raise%20proper%20form'),
  ('11111111-1111-4111-8111-111111111163', null, 'Chest Press Machine', 'strength', 'weight_reps', array['chest', 'triceps', 'shoulders'], array['machine'], 'Handles at mid-chest, press to lockout without shrugging, then return with control.', 'https://www.youtube.com/results?search_query=Chest%20Press%20Machine%20proper%20form'),
  ('11111111-1111-4111-8111-111111111164', null, 'Pec Deck', 'strength', 'weight_reps', array['chest'], array['pec deck'], 'Bring the pads together in a hugging motion and return until a comfortable chest stretch.', 'https://www.youtube.com/results?search_query=Pec%20Deck%20proper%20form'),
  ('11111111-1111-4111-8111-111111111165', null, 'Lat Pulldown', 'strength', 'weight_reps', array['lats', 'biceps', 'upper back'], array['cable'], 'Pull the bar to the upper chest, elbows down, then let the shoulders reach up on the return.', 'https://www.youtube.com/results?search_query=Lat%20Pulldown%20proper%20form'),
  ('11111111-1111-4111-8111-111111111166', null, 'Seated Cable Row', 'strength', 'weight_reps', array['upper back', 'lats', 'biceps'], array['cable'], 'Row the handle to the belly, squeeze the shoulder blades, and extend the arms fully each rep.', 'https://www.youtube.com/results?search_query=Seated%20Cable%20Row%20proper%20form'),
  ('11111111-1111-4111-8111-111111111167', null, 'Face Pull', 'strength', 'weight_reps', array['rear delts', 'upper back'], array['cable', 'rope'], 'Pull the rope to the face, externally rotating so the knuckles point back. Pause and return.', 'https://www.youtube.com/results?search_query=Face%20Pull%20proper%20form'),
  ('11111111-1111-4111-8111-111111111168', null, 'Cable Fly', 'strength', 'weight_reps', array['chest'], array['cable'], 'From a slight forward lean, bring the handles together in a wide arc and control the opening.', 'https://www.youtube.com/results?search_query=Cable%20Fly%20proper%20form'),
  ('11111111-1111-4111-8111-111111111169', null, 'Triceps Pushdown', 'strength', 'weight_reps', array['triceps'], array['cable'], 'Elbows pinned to the sides, extend the arms fully and return to about 90 degrees.', 'https://www.youtube.com/results?search_query=Triceps%20Pushdown%20proper%20form'),
  ('11111111-1111-4111-8111-111111111170', null, 'Cable Biceps Curl', 'strength', 'weight_reps', array['biceps'], array['cable'], 'Curl the bar or handle without letting the elbows travel forward. Lower slowly.', 'https://www.youtube.com/results?search_query=Cable%20Biceps%20Curl%20proper%20form'),
  ('11111111-1111-4111-8111-111111111171', null, 'Cable Crunch', 'strength', 'weight_reps', array['abs'], array['cable'], 'Kneel, hold the rope at the head, and crunch the ribs toward the pelvis. Do not pull with the arms.', 'https://www.youtube.com/results?search_query=Cable%20Crunch%20proper%20form'),
  ('11111111-1111-4111-8111-111111111172', null, 'Hip Abduction Machine', 'strength', 'weight_reps', array['glutes'], array['machine'], 'Push the pads apart against the resistance and return without letting the stack slam.', 'https://www.youtube.com/results?search_query=Hip%20Abduction%20Machine%20proper%20form'),
  ('11111111-1111-4111-8111-111111111173', null, 'Hip Adduction Machine', 'strength', 'weight_reps', array['adductors'], array['machine'], 'Squeeze the pads together and control the opening. Keep the torso still.', 'https://www.youtube.com/results?search_query=Hip%20Adduction%20Machine%20proper%20form'),
  ('11111111-1111-4111-8111-111111111174', null, 'Chin-Up', 'strength', 'weight_reps', array['lats', 'biceps'], array['pull-up bar'], 'Underhand grip, pull until the chin clears the bar, then lower to a dead hang.', 'https://www.youtube.com/results?search_query=Chin-Up%20proper%20form'),
  ('11111111-1111-4111-8111-111111111175', null, 'Neutral-Grip Pull-Up', 'strength', 'weight_reps', array['lats', 'biceps', 'upper back'], array['pull-up bar'], 'Use parallel handles. Pull the elbows down until the chest approaches the bar, then lower fully.', 'https://www.youtube.com/results?search_query=Neutral-Grip%20Pull-Up%20proper%20form'),
  ('11111111-1111-4111-8111-111111111176', null, 'Dip', 'strength', 'weight_reps', array['chest', 'triceps', 'shoulders'], array['dip bars'], 'Lean slightly forward, lower until the shoulders are below the elbows, then press up.', 'https://www.youtube.com/results?search_query=Dip%20proper%20form'),
  ('11111111-1111-4111-8111-111111111177', null, 'Push-Up', 'strength', 'reps', array['chest', 'triceps', 'shoulders', 'core'], array['bodyweight'], 'Hands under the shoulders, body in a straight line. Lower the chest to the floor and press back up.', 'https://www.youtube.com/results?search_query=Push-Up%20proper%20form'),
  ('11111111-1111-4111-8111-111111111178', null, 'Diamond Push-Up', 'strength', 'reps', array['triceps', 'chest'], array['bodyweight'], 'Hands close together under the chest. Keep the elbows tucked and the body rigid.', 'https://www.youtube.com/results?search_query=Diamond%20Push-Up%20proper%20form'),
  ('11111111-1111-4111-8111-111111111179', null, 'Pike Push-Up', 'strength', 'reps', array['shoulders', 'triceps'], array['bodyweight'], 'Hips high in a pike, lower the head toward the floor between the hands, then press up.', 'https://www.youtube.com/results?search_query=Pike%20Push-Up%20proper%20form'),
  ('11111111-1111-4111-8111-111111111180', null, 'Inverted Row', 'strength', 'reps', array['upper back', 'biceps'], array['bar', 'rings'], 'Hang under a bar with a straight body. Pull the chest to the bar and lower with control.', 'https://www.youtube.com/results?search_query=Inverted%20Row%20proper%20form'),
  ('11111111-1111-4111-8111-111111111181', null, 'Pistol Squat', 'strength', 'reps', array['quads', 'glutes', 'core'], array['bodyweight'], 'Stand on one leg, reach the other forward, and sit as low as you can control. Stand without falling to the side.', 'https://www.youtube.com/results?search_query=Pistol%20Squat%20proper%20form'),
  ('11111111-1111-4111-8111-111111111182', null, 'Nordic Hamstring Curl', 'strength', 'reps', array['hamstrings'], array['partner or Nordic bench'], 'Kneel with ankles fixed, lower the torso forward as slowly as possible, then pull back or push up to reset.', 'https://www.youtube.com/results?search_query=Nordic%20Hamstring%20Curl%20proper%20form'),
  ('11111111-1111-4111-8111-111111111183', null, 'Hanging Leg Raise', 'strength', 'reps', array['abs', 'hip flexors'], array['pull-up bar'], 'Hang still and raise the legs to at least parallel without swinging. Lower slowly.', 'https://www.youtube.com/results?search_query=Hanging%20Leg%20Raise%20proper%20form'),
  ('11111111-1111-4111-8111-111111111184', null, 'Plank', 'strength', 'duration', array['core'], array['mat'], 'Elbows under the shoulders, body in a straight line. Brace as if expecting a punch and breathe.', 'https://www.youtube.com/results?search_query=Plank%20proper%20form'),
  ('11111111-1111-4111-8111-111111111185', null, 'Side Plank', 'strength', 'duration', array['obliques', 'core'], array['mat'], 'Stack the feet, lift the hips, and keep a straight line from head to heels. Switch sides halfway if needed.', 'https://www.youtube.com/results?search_query=Side%20Plank%20proper%20form'),
  ('11111111-1111-4111-8111-111111111186', null, 'Hollow Hold', 'strength', 'duration', array['abs'], array['mat'], 'Press the low back into the floor, lift the shoulders and legs, and hold the banana shape.', 'https://www.youtube.com/results?search_query=Hollow%20Hold%20proper%20form'),
  ('11111111-1111-4111-8111-111111111187', null, 'Superman Hold', 'strength', 'duration', array['lower back', 'glutes'], array['mat'], 'Lie prone and lift the chest, arms, and legs off the floor. Keep the neck long.', 'https://www.youtube.com/results?search_query=Superman%20Hold%20proper%20form'),
  ('11111111-1111-4111-8111-111111111188', null, 'Burpee', 'strength', 'reps', array['full body'], array['bodyweight'], 'Squat, plant the hands, jump the feet back, do a push-up if planned, jump the feet in, and stand or jump.', 'https://www.youtube.com/results?search_query=Burpee%20proper%20form'),
  ('11111111-1111-4111-8111-111111111189', null, 'Mountain Climber', 'strength', 'duration', array['core', 'hip flexors'], array['mat'], 'From a high plank, drive the knees toward the chest in a steady rhythm without bouncing the hips.', 'https://www.youtube.com/results?search_query=Mountain%20Climber%20proper%20form'),
  ('11111111-1111-4111-8111-111111111190', null, 'Outdoor Run', 'cardio', 'distance_duration', array['full body'], array['none'], 'Run outdoors at the planned pace. Log only the running portion, not walking warm-up.', 'https://www.youtube.com/results?search_query=Outdoor%20Run%20proper%20form'),
  ('11111111-1111-4111-8111-111111111191', null, 'Outdoor Walk', 'cardio', 'distance_duration', array['full body'], array['none'], 'Brisk walk. Log total walking distance and duration.', 'https://www.youtube.com/results?search_query=Outdoor%20Walk%20proper%20form'),
  ('11111111-1111-4111-8111-111111111192', null, 'Elliptical', 'cardio', 'distance_duration', array['full body'], array['elliptical'], 'Stand tall, drive through the whole foot, and keep a smooth cadence for the planned time and distance.', 'https://www.youtube.com/results?search_query=Elliptical%20proper%20form'),
  ('11111111-1111-4111-8111-111111111193', null, 'Stair Climber', 'cardio', 'duration', array['quads', 'glutes', 'calves'], array['stair machine'], 'Stand upright, take full steps, and avoid leaning heavily on the rails.', 'https://www.youtube.com/results?search_query=Stair%20Climber%20proper%20form'),
  ('11111111-1111-4111-8111-111111111194', null, 'Assault Bike', 'cardio', 'distance_duration', array['full body'], array['air bike'], 'Push and pull the handles while pedaling. Log the machine distance and time.', 'https://www.youtube.com/results?search_query=Assault%20Bike%20proper%20form'),
  ('11111111-1111-4111-8111-111111111195', null, 'SkiErg', 'cardio', 'distance_duration', array['lats', 'core', 'legs'], array['SkiErg'], 'Hinge and pull the handles down past the hips, then recover tall. Log distance and duration.', 'https://www.youtube.com/results?search_query=SkiErg%20proper%20form'),
  ('11111111-1111-4111-8111-111111111196', null, 'Swimming', 'cardio', 'distance_duration', array['full body'], array['pool'], 'Log the total swimming distance and time, excluding rest at the wall if you prefer work-only.', 'https://www.youtube.com/results?search_query=Swimming%20proper%20form'),
