  ('11111111-1111-4111-8111-111111111198', null, 'Hiking', 'cardio', 'distance_duration', array['full body'], array['none'], 'Log the trail distance and total moving time. Note elevation in the session notes if useful.', 'https://www.youtube.com/results?search_query=Hiking%20proper%20form'),
