  ('11111111-1111-4111-8111-111111111200', null, 'World''s Greatest Stretch', 'mobility', 'duration', array['hips', 'thoracic spine', 'hamstrings'], array['mat'], 'From a lunge, plant the inside hand and rotate the other arm to the sky, then sit the hips back to stretch the hamstring. Alternate sides.', 'https://www.youtube.com/results?search_query=World''s%20Greatest%20Stretch%20proper%20form'),
  ('11111111-1111-4111-8111-111111111201', null, 'Pigeon Stretch', 'mobility', 'duration', array['glutes', 'hips'], array['mat'], 'Front shin across, back leg long. Keep the hips square and fold forward as comfortable. Switch sides.', 'https://www.youtube.com/results?search_query=Pigeon%20Stretch%20proper%20form'),
  ('11111111-1111-4111-8111-111111111202', null, 'Hamstring Stretch', 'mobility', 'duration', array['hamstrings'], array['mat'], 'Hinge over a straight or slightly bent leg until a gentle stretch. Breathe and do not bounce.', 'https://www.youtube.com/results?search_query=Hamstring%20Stretch%20proper%20form'),
  ('11111111-1111-4111-8111-111111111203', null, 'Couch Stretch', 'mobility', 'duration', array['hip flexors', 'quads'], array['bench or wall'], 'Rear foot up on a wall or couch, front foot planted. Tuck the pelvis and stay tall. Switch sides.', 'https://www.youtube.com/results?search_query=Couch%20Stretch%20proper%20form'),
  ('11111111-1111-4111-8111-111111111204', null, '90/90 Hip Stretch', 'mobility', 'duration', array['hips', 'glutes'], array['mat'], 'Both knees at 90 degrees. Sit tall, then slowly rotate to the other side.', 'https://www.youtube.com/results?search_query=90%2F90%20Hip%20Stretch%20proper%20form'),
  ('11111111-1111-4111-8111-111111111205', null, 'Shoulder Dislocate', 'mobility', 'duration', array['shoulders'], array['band or stick'], 'Hold a wide grip and sweep the arms over the head and behind without forcing the end range.', 'https://www.youtube.com/results?search_query=Shoulder%20Dislocate%20proper%20form'),
  ('11111111-1111-4111-8111-111111111206', null, 'Band Pull-Apart', 'mobility', 'reps', array['rear delts', 'upper back'], array['band'], 'Hold a band at chest height and pull it apart until it touches the chest. Control the return.', 'https://www.youtube.com/results?search_query=Band%20Pull-Apart%20proper%20form'),
  ('11111111-1111-4111-8111-111111111207', null, 'Child''s Pose', 'mobility', 'duration', array['back', 'hips'], array['mat'], 'Sit the hips toward the heels, arms long, and breathe into the back.', 'https://www.youtube.com/results?search_query=Child''s%20Pose%20proper%20form'),
  ('11111111-1111-4111-8111-111111111208', null, 'Downward Dog', 'mobility', 'duration', array['hamstrings', 'calves', 'shoulders'], array['mat'], 'Hips high, heels reaching down, arms long. Pedal the feet and keep a long spine.', 'https://www.youtube.com/results?search_query=Downward%20Dog%20proper%20form'),
  ('11111111-1111-4111-8111-111111111209', null, 'Thread the Needle', 'mobility', 'duration', array['thoracic spine', 'shoulders'], array['mat'], 'From all fours, slide one arm under the other and rest on the shoulder. Breathe, then switch.', 'https://www.youtube.com/results?search_query=Thread%20the%20Needle%20proper%20form'),
  ('11111111-1111-4111-8111-111111111210', null, 'Dead Hang', 'mobility', 'duration', array['shoulders', 'lats', 'grip'], array['pull-up bar'], 'Hang passively or with a light scapular set. Relax the shoulders as far as comfortable and breathe.', 'https://www.youtube.com/results?search_query=Dead%20Hang%20proper%20form'),
  ('11111111-1111-4111-8111-111111111211', null, 'Pec Doorway Stretch', 'mobility', 'duration', array['chest', 'shoulders'], array['doorway'], 'Forearm on a doorframe, step through until a stretch across the chest. Switch sides.', 'https://www.youtube.com/results?search_query=Pec%20Doorway%20Stretch%20proper%20form'),
  ('11111111-1111-4111-8111-111111111212', null, 'Ankle Rocks', 'mobility', 'duration', array['ankles'], array['mat'], 'In a half-kneeling stance, drive the front knee over the toes without lifting the heel. Switch sides.', 'https://www.youtube.com/results?search_query=Ankle%20Rocks%20proper%20form'),
  ('11111111-1111-4111-8111-111111111213', null, 'Foam Roll Quads', 'mobility', 'duration', array['quads'], array['foam roller'], 'Roll slowly from hip to knee, pausing on tender spots. Keep the core braced.', 'https://www.youtube.com/results?search_query=Foam%20Roll%20Quads%20proper%20form'),
