-- Expand the system catalog and attach a YouTube *search* link for every exercise.
-- Search URLs are used on purpose: we do not invent specific video IDs that can rot or be wrong.
-- The app opens "Watch form videos on YouTube" which always returns current form demos.

-- Existing seed rows: only fill video_url.
update public.exercises set video_url = 'https://www.youtube.com/results?search_query=Barbell%20Back%20Squat%20proper%20form' where id = '11111111-1111-4111-8111-111111111101' and owner_id is null;
